"""Build the requested owner evidence review from existing QQQ TRAIN artifacts."""
from pathlib import Path
import json, math
import numpy as np
import pandas as pd

ROOT=Path("research_outputs/qqq_entry_discovery_agent_v1"); ART=ROOT/"artifacts"
def load(n): return json.loads((ART/n).read_text())
def metric(g):
    g=g.copy(); p=pd.to_numeric(g.realized_pnl,errors="coerce").dropna(); pos=p[p>0]; neg=p[p<0]
    return {"trades":int(len(p)),"total_pnl":float(p.sum()),"expectancy":float(p.mean()) if len(p) else None,"profit_factor":float(pos.sum()/abs(neg.sum())) if len(neg) else None,"win_rate":float((p>0).mean()) if len(p) else None,"stop_count":int(g.stopped.fillna(False).sum()) if "stopped" in g else None,"stop_rate":float(g.stopped.fillna(False).mean()) if "stopped" in g else None,"average_win":float(pos.mean()) if len(pos) else None,"average_loss":float(neg.mean()) if len(neg) else None,"payoff_ratio":float(pos.mean()/abs(neg.mean())) if len(pos) and len(neg) else None,"worst_trade":float(p.min()) if len(p) else None,"best_trade":float(p.max()) if len(p) else None,"median_pnl":float(p.median()) if len(p) else None}
def year_metrics(g): return {str(y):metric(x) for y,x in g.assign(year=pd.to_datetime(g.trade_date).dt.year).groupby("year")}
def concentration(g):
    p=g.realized_pnl.sort_values(ascending=False); total=float(p[p>0].sum()); years=g.assign(year=pd.to_datetime(g.trade_date).dt.year).groupby("year").realized_pnl.sum().sort_values(ascending=False); yt=years[years>0].sum()
    return {"top_episode_pnl_share":float(p.head(1).sum()/total) if total else None,"top_2_episodes_pnl_share":float(p.head(2).sum()/total) if total else None,"top_3_episodes_pnl_share":float(p.head(3).sum()/total) if total else None,"profitable_episodes":int((g.realized_pnl>0).sum()),"losing_episodes":int((g.realized_pnl<0).sum()),"median_episode_pnl":float(g.realized_pnl.median()),"worst_episode_pnl":float(g.realized_pnl.min()),"positive_year_shares":{str(k):float(v/yt) for k,v in years[years>0].items()} if yt else {},"top_year_pnl_share":float(years.head(1).sum()/yt) if yt else None,"top_2_years_pnl_share":float(years.head(2).sum()/yt) if yt else None}
def loo(g):
    vals=[]
    for i in g.index:
        x=g.drop(i); vals.append(metric(x))
    return {"min_loo_total_pnl":min(x["total_pnl"] for x in vals) if vals else None,"min_loo_expectancy":min(x["expectancy"] for x in vals) if vals else None,"negative_loo_count":sum(x["total_pnl"]<0 for x in vals)}
def candidate(id,name,rule,source,qualifying=None,episodes=None):
    x=source.copy(); x.trade_date=pd.to_datetime(x.trade_date); out={"HYPOTHESIS_ID":id,"descriptive_name":name,"setup_family":name,"exact_rule":rule,"qualifying_dates":qualifying,"unique_dates":qualifying,"independent_episodes":episodes,"executable_episodes":episodes,"status":"DESCRIPTIVE_ONLY","performance":metric(x),"year_performance":year_metrics(x),"episode_robustness":{**concentration(x),**loo(x)},"contract_robustness":"NOT_TESTED","contract_integrity":"not available in this descriptive artifact","discovery_controls":{"qqq_only":True,"validation_read":False,"final_oos_read":False,"production_changes":False}}
    return out
def episode_first(frame, calendar):
    """Group qualifying dates by adjacent sessions, never calendar-day gaps."""
    x=frame.sort_values("trade_date").copy()
    sessions=pd.DatetimeIndex(pd.to_datetime(calendar).dt.normalize().drop_duplicates().sort_values())
    positions=pd.Series(range(len(sessions)),index=sessions)
    x["_session_index"]=pd.to_datetime(x.trade_date).dt.normalize().map(positions)
    if x["_session_index"].isna().any():
        raise ValueError("QQQ_TRAIN_SESSION_INDEX_INCOMPLETE")
    x["episode"]=(x["_session_index"].diff().fillna(999).ne(1)).cumsum()
    return x.groupby("episode",as_index=False).first()
