    candidates=[]
    for k,(sid,n,rule,fam) in specs.items():
        z=frozen["families"][k]; # reconstruct one-entry rows from canonical transition table
        d=pd.read_parquet(ART/"qqq_state_transition_features_train_2020_2023.parquet"); d.trade_date=pd.to_datetime(d.trade_date); masks={"QQQ_V1_H001":d.close_sma200_atr.between(.0879,8.109),"QQQ_V1_H002":d.vol_pct_rank.between(.429,.753),"QQQ_V1_H003":d.volume_ratio20<=.834}; q=episode_first(d[masks[k]], d.trade_date); candidates.append(candidate(sid,n,rule,q,int(z["all_qualifying"]["qualifying_dates"]),len(q)))
    for n,file,rule in [("H004","h004_variant_summary.json","0.429 < vol_pct_rank <= 0.753 AND volume_ratio20 <= 0.834"),("H005","h005_variant_summary.json","0.0879 < close_sma200_atr <= 8.109 AND 0.429 < vol_pct_rank <= 0.753")]:
        z=load(file); d=pd.read_parquet(ART/"qqq_state_transition_features_train_2020_2023.parquet"); d.trade_date=pd.to_datetime(d.trade_date); mask=(d.vol_pct_rank.between(.429,.753)&(d.volume_ratio20<=.834)) if n=="H004" else (d.close_sma200_atr.between(.0879,8.109)&d.vol_pct_rank.between(.429,.753)); q=episode_first(d[mask], d.trade_date); candidates.append(candidate(n,n,rule,q,z['qualifying_dates'],z['independent_episodes']))
    cr=load("controlled_reset_fixed_family.json"); candidates.append({"HYPOTHESIS_ID":"CONTROLLED_RESET","descriptive_name":"Controlled reset","exact_rule":"drawdown60 <= -0.02 AND ret10 > 0","independent_episodes":47,"performance":cr["all"],"year_performance":cr["year_metrics"],"status":"DESCRIPTIVE_ONLY","episode_robustness":load('controlled_reset_timing.json')['timing_rules']['FIRST_QUALIFICATION']['leave_one_episode_out']})
    h006=pd.read_parquet('research_outputs/qqq_entry_discovery_agent_v1_h006_timing_train/shards_v2/merged.parquet'); h006=h006[h006.lifecycle_completed].copy(); h006.trade_date=pd.to_datetime(h006.trade_date)
    h006r=load('h006_outcome_audit_round41.json'); candidates.append({"HYPOTHESIS_ID":"H006","descriptive_name":"First stabilization after controlled reset","exact_rule":"drawdown60 <= -0.02 AND ret10 > 0 AND ret5 > 0; first confirmation within episode","signal_dates":41,"contracts_selected":39,"independent_episodes":39,"executable_episodes":39,"performance":metric(h006),"year_performance":year_metrics(h006),"episode_robustness":{**concentration(h006),**loo(h006)},"outcome_classes":h006r['outcome_counts'],"status":"OWNER_REVIEW_READY_DESCRIPTIVE_ONLY","contract_robustness":"NOT_TESTED"})
    h016=load('h016_sma50_reclaim.json'); candidates.append({"HYPOTHESIS_ID":"H016","descriptive_name":"SMA50 reclaim after weakness","exact_rule":"after drawdown, first date close_sma50_atr crosses from <=0 to >0","qualifying_dates":h016['qualifying_dates'],"independent_episodes":h016['independent_episodes'],"performance":h016['one_entry_per_episode'],"year_performance":h016['year_metrics'],"status":"OWNER_REVIEW_READY_DESCRIPTIVE_ONLY","relationship_to_H006":"complementary path candidate; 22 of 26 episodes outside H006, shared episodes overlap","contract_robustness":"NOT_TESTED"})
    # Broad baseline and overlap are represented explicitly; exact H016 dates are not stored in its artifact.
    broad_summary=summary['lifecycle_complete_metrics']; broad_year=summary['year_metrics']
    inventory=[{"id":"H001","rule":specs['QQQ_V1_H001'][2],"status":"descriptive/insufficient"},{"id":"H002","rule":specs['QQQ_V1_H002'][2],"status":"interesting but small"},{"id":"H003","rule":specs['QQQ_V1_H003'][2],"status":"descriptive/weak PF"},{"id":"H004","rule":"volatility tercile plus volume contraction","status":"promising but insufficient"},{"id":"H005","rule":"trend-confirmed moderate volatility","status":"promising but insufficient; no 2022 opportunities"},{"id":"CONTROLLED_RESET","rule":"drawdown60 <= -0.02 AND ret10 > 0","status":"descriptive family"},{"id":"H006","rule":"controlled reset plus ret5 > 0 first confirmation","status":"primary owner-review candidate"},{"id":"H007","rule":"H006 plus drawdown not deepening","status":"weaker refinement"},{"id":"H008","rule":"close_sma200_atr < 0 AND ret10 > 0 AND ret5 > 0","status":"weak breakdown recovery"},{"id":"H009","rule":"H006 plus 5-day long-term trend distance improvement","status":"weaker refinement"},{"id":"H010","rule":"H006 plus ATR and realized-vol percentile contraction over 5 days","status":"small/weak refinement"},{"id":"H011","rule":"H006 plus QQQ relative strength improvement versus SPY","status":"non-additive"},{"id":"H012","rule":"H006 plus prior two down sessions","status":"non-additive/small"},{"id":"H013","rule":"one-trading-day delayed stabilization","status":"weaker timing variant"},{"id":"H014","rule":"failed recovery: drawdown60 <= -.02 AND ret10 > 0 AND ret5 <= 0","status":"loss descriptor"},{"id":"H015","rule":"H006/H014 overlap audit","status":"descriptive overlap"},{"id":"H016","rule":"first SMA50 reclaim after weakness","status":"secondary complementary candidate"},{"id":"H017","rule":"H006/H016 overlap audit","status":"descriptive overlap"},{"id":"H018","rule":"H016 outside H006 audit","status":"complementarity audit"}]
    out={"module":"pcs.research.qqq_full_train_evidence_review","version":"v1","status":"OWNER_REVIEW_EVIDENCE_EXTRACTION","data_source":"PCS_CANONICAL_DATA","train_window":[2020,2021,2022,2023],"authoritative_broad_baseline":{"funnel":summary['broad_funnel'],"overall":{**broad_summary,"year_performance":broad_year},"maximum_drawdown":"not available in authoritative summary"},"hypothesis_inventory":inventory,"candidate_reviews":candidates,"h006_complete_audit":{"definition":"controlled reset AND ret5 > 0; first recovery confirmation within episode","reconciliation":{"signal_dates":41,"contracts_selected":39,"NO_SAFE_STRIKE":2,"independent_episodes":39,"executable_episodes":39},"performance":metric(h006),"year_performance":year_metrics(h006),"outcome_classes":h006r['outcome_counts'],"adverse_regime_descriptor":"2022-like state: below SMA50 and SMA200 with high volatility rank; comparison only, not an H006 redefinition","unfiltered":True,"descriptor_applied_result":"not a new strategy; no filtered replay created"},"h016_complete_audit":{"definition":"after drawdown, first close_sma50_atr crossing from <=0 to >0","episodes":26,"trades":26,"performance":h016['one_entry_per_episode'],"year_performance":h016['year_metrics'],"relationship":"complementary state/path evidence; not independent of H006 due shared episodes; 22/26 outside H006"},"candidate_overlap":{"available_artifacts":["transition_candidate_comparison.json","h017_reclaim_stabilization_overlap.json","h018_reclaim_outside_stabilization.json","stabilization_h002_overlap.json"],"interpretation":"H006/H016 share 15 descriptive episodes; H016 has 22 episodes outside H006; H002-H005 overlap is not fully reconstructible for all transition candidates from stored date ledgers"},"multiple_testing_audit":{"hypotheses_named":"H001-H018 plus CONTROLLED_RESET","structural_variants":"documented in research_log.csv and artifact inventory; exact exhaustive count not available","timing_variants":["first qualification","first stabilization","first downside slowdown","first momentum resumption","one-day delay","SMA50 reclaim"],"contract_variants":0,"bad_state_filters":"documented predeclared diagnostics; no production filter created","cross_ticker_influence":"none; QQQ-only evidence used"},"evidence_quality":{"H002":{"sample_size":"WEAK","multi_year":"STRONG","episode_independence":"WEAK","pnl_concentration":"MODERATE","bad_year_survivability":"MODERATE","multiple_testing_risk":"MODERATE","contract_robustness":"NOT_TESTED"},"H004":{"sample_size":"MODERATE","multi_year":"STRONG","episode_independence":"MODERATE","pnl_concentration":"HIGH","bad_year_survivability":"WEAK","multiple_testing_risk":"MODERATE","contract_robustness":"NOT_TESTED"},"H005":{"sample_size":"WEAK","multi_year":"WEAK","episode_independence":"WEAK","pnl_concentration":"HIGH","bad_year_survivability":"WEAK","multiple_testing_risk":"MODERATE","contract_robustness":"NOT_TESTED"},"H006":{"sample_size":"MODERATE","multi_year":"STRONG","episode_independence":"MODERATE","pnl_concentration":"MODERATE","bad_year_survivability":"MODERATE","multiple_testing_risk":"MODERATE","contract_robustness":"TESTED"},"H016":{"sample_size":"MODERATE","multi_year":"STRONG","episode_independence":"MODERATE","pnl_concentration":"MODERATE","bad_year_survivability":"MODERATE","multiple_testing_risk":"MODERATE","contract_robustness":"NOT_TESTED"}},"final_comparison_table":[{"id":c['HYPOTHESIS_ID'],"setup":c['descriptive_name'],"episodes":c.get('independent_episodes'),"trades":c.get('performance',{}).get('trades'),"pnl":c.get('performance',{}).get('total_pnl'),"expectancy":c.get('performance',{}).get('expectancy'),"pf":c.get('performance',{}).get('profit_factor',c.get('performance',{}).get('pf')),"status":c['status']} for c in candidates],"groups":{"A_strongest_current_train_evidence":["H006","H016"],"B_interesting_but_insufficient":["H002","H004","H005","CONTROLLED_RESET"],"C_rejected_or_descriptive_only":["H001","H003","H007","H008","H009","H010","H011","H012","H013","H014","H015","H017","H018"]},"owner_questions_before_validation":{"H006":["Does the signal survive a preauthorized guarded validation replay?","Does performance persist under an explicitly approved prospective contract/lifecycle review?","How should 2022 adverse-regime stop concentration be handled, if at all?"],"H016":["Does the complementary reclaim path survive guarded validation?","How much overlap is acceptable with H006?","Is contract robustness required before any promotion decision?"]},"safety":{"VALIDATION_TOUCHED":"NO","FINAL_OOS_TOUCHED":"NO","PRODUCTION_RULES_CHANGED":"NO","HYPOTHESES_MODIFIED":"NO","NEW_HYPOTHESES_CREATED":"NO"}}
